<script dangerouslySetInnerHTML={{__html:"\r\n  (function(){\r\n    var track    = document.getElementById('testimonialsTrack');\r\n    var prevBtn  = document.getElementById('testimonialsPrevBtn');\r\n    var nextBtn  = document.getElementById('testimonialsNextBtn');\r\n    var dotsWrap = document.getElementById('testimonialsDots');\r\n    if (!track) return;\r\n\r\n    var cards = track.querySelectorAll('.testimonial-card');\r\n    var total = cards.length;\r\n    var current = 0;\r\n    var gap = 20;\r\n\r\n    /* ---- Carousel ---- */\r\n    function visibleCount() {\r\n      var w = window.innerWidth;\r\n      if (w >= 1100) return 4;\r\n      if (w >= 700)  return 2;\r\n      return 1;\r\n    }\r\n\r\n    function buildDots() {\r\n      dotsWrap.innerHTML = '';\r\n      var pages = Math.ceil(total / visibleCount());\r\n      for (var i = 0; i < pages; i++) {\r\n        var btn = document.createElement('button');\r\n        btn.className = 'testimonials-dot' + (i === 0 ? ' active' : '');\r\n        btn.setAttribute('aria-label', 'Page ' + (i + 1));\r\n        btn.dataset.page = i;\r\n        btn.addEventListener('click', function(){ goTo(+this.dataset.page * visibleCount()); });\r\n        dotsWrap.appendChild(btn);\r\n      }\r\n    }\r\n\r\n    function updateDots() {\r\n      var activePage = Math.round(current / visibleCount());\r\n      dotsWrap.querySelectorAll('.testimonials-dot').forEach(function(d, i){\r\n        d.classList.toggle('active', i === activePage);\r\n      });\r\n    }\r\n\r\n    function goTo(index) {\r\n      var vc = visibleCount();\r\n      var max = total - vc;\r\n      current = Math.max(0, Math.min(index, max));\r\n      var cardW = cards[0].offsetWidth + gap;\r\n      track.style.transform = 'translateX(-' + (current * cardW) + 'px)';\r\n      prevBtn.disabled = current === 0;\r\n      nextBtn.disabled = current >= total - vc;\r\n      updateDots();\r\n    }\r\n\r\n    prevBtn.addEventListener('click', function(){ goTo(current - visibleCount()); });\r\n    nextBtn.addEventListener('click', function(){ goTo(current + visibleCount()); });\r\n    window.addEventListener('resize', function(){ buildDots(); goTo(0); });\r\n\r\n    buildDots();\r\n    goTo(0);\r\n\r\n    /* ---- YouTube IFrame API: pause others on play ---- */\r\n    var iframes = track.querySelectorAll('iframe');\r\n    var ytPlayers = [];\r\n\r\n    // Give each iframe a unique ID so YT.Player can target it\r\n    iframes.forEach(function(f, i) {\r\n      f.id = 'tYTPlayer' + i;\r\n    });\r\n\r\n    function pauseAllExcept(activeIdx) {\r\n      ytPlayers.forEach(function(p, i) {\r\n        if (i !== activeIdx && p && typeof p.pauseVideo === 'function') {\r\n          try { p.pauseVideo(); } catch(e) {}\r\n        }\r\n      });\r\n    }\r\n\r\n    function initYTPlayers() {\r\n      iframes.forEach(function(f, idx) {\r\n        ytPlayers[idx] = new YT.Player(f.id, {\r\n          events: {\r\n            onStateChange: (function(i) {\r\n              return function(e) {\r\n                if (e.data === YT.PlayerState.PLAYING) pauseAllExcept(i);\r\n              };\r\n            })(idx)\r\n          }\r\n        });\r\n      });\r\n    }\r\n\r\n    // Load YouTube IFrame API once (safe if already loaded by another section)\r\n    if (typeof YT !== 'undefined' && typeof YT.Player !== 'undefined') {\r\n      initYTPlayers();\r\n    } else {\r\n      var _prev = window.onYouTubeIframeAPIReady;\r\n      window.onYouTubeIframeAPIReady = function() {\r\n        if (typeof _prev === 'function') _prev();\r\n        initYTPlayers();\r\n      };\r\n      if (!document.querySelector('script[src*=\"youtube.com/iframe_api\"]')) {\r\n        var tag = document.createElement('script');\r\n        tag.src = 'https://www.youtube.com/iframe_api';\r\n        document.head.appendChild(tag);\r\n      }\r\n    }\r\n  })();\r\n  "}} />





    
