{/* book your demo script */}


<script dangerouslySetInnerHTML={{__html:"\r\n(function(){\r\n\r\n  // =========================================================\r\n  // GOOGLE SHEET URL\r\n  // =========================================================\r\n  const SHEET_URL = '/api/forms/book-demo';\r\n\r\n  // =========================================================\r\n  // CALENDAR VARIABLES\r\n  // =========================================================\r\n  const monthNames = [\r\n    'January','February','March','April','May','June',\r\n    'July','August','September','October','November','December'\r\n  ];\r\n\r\n  const today = new Date();\r\n\r\n  let selectedDate = null;\r\n  let viewYear  = today.getFullYear();\r\n  let viewMonth = today.getMonth();\r\n\r\n  // =========================================================\r\n  // ELEMENTS\r\n  // =========================================================\r\n  const monthLabel = document.getElementById('bdCalMonthLabel');\r\n  const grid       = document.getElementById('bdCalGrid');\r\n  const form       = document.getElementById('bookDemoForm');\r\n\r\n  if(!monthLabel || !grid || !form){\r\n    console.warn('❌ Book Demo elements not found');\r\n    return;\r\n  }\r\n\r\n  const btnText   = document.getElementById('bdBtnText');\r\n  const btnLoader = document.getElementById('bdBtnLoader');\r\n  const submitBtn = document.getElementById('bdSubmitBtn');\r\n  const status    = document.getElementById('bdStatus');\r\n\r\n  // =========================================================\r\n  // CALENDAR ICON\r\n  // =========================================================\r\n  const CAL_ICON = `\r\n  <svg xmlns=\"http://www.w3.org/2000/svg\"\r\n       fill=\"none\"\r\n       viewBox=\"0 0 24 24\"\r\n       stroke-width=\"1.8\"\r\n       stroke=\"currentColor\"\r\n       style=\"width:16px;height:16px;flex-shrink:0\">\r\n    <path stroke-linecap=\"round\"\r\n          stroke-linejoin=\"round\"\r\n          d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5\"/>\r\n  </svg>\r\n  `;\r\n\r\n  // =========================================================\r\n  // HELPERS\r\n  // =========================================================\r\n  function fmtISO(d){\r\n    const y = d.getFullYear();\r\n    const m = String(d.getMonth() + 1).padStart(2,'0');\r\n    const day = String(d.getDate()).padStart(2,'0');\r\n\r\n    return `${y}-${m}-${day}`;\r\n  }\r\n\r\n  function fmtDisplay(d){\r\n    return d.toLocaleDateString('en-IN',{\r\n      day:'numeric',\r\n      month:'long',\r\n      year:'numeric'\r\n    });\r\n  }\r\n\r\n  function sameDate(a,b){\r\n    return (\r\n      a &&\r\n      b &&\r\n      a.getFullYear() === b.getFullYear() &&\r\n      a.getMonth() === b.getMonth() &&\r\n      a.getDate() === b.getDate()\r\n    );\r\n  }\r\n\r\n  function isPastDate(dateObj){\r\n\r\n    const now = new Date();\r\n\r\n    now.setHours(0,0,0,0);\r\n\r\n    const dt = new Date(\r\n      dateObj.getFullYear(),\r\n      dateObj.getMonth(),\r\n      dateObj.getDate()\r\n    );\r\n\r\n    return dt < now;\r\n  }\r\n\r\n  // =========================================================\r\n  // RENDER CALENDAR\r\n  // =========================================================\r\n  function renderCalendar(){\r\n\r\n    monthLabel.textContent =\r\n      monthNames[viewMonth] + ' ' + viewYear;\r\n\r\n    grid.innerHTML = '';\r\n\r\n    const firstDay    = new Date(viewYear, viewMonth, 1);\r\n    const startDay    = firstDay.getDay();\r\n    const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();\r\n\r\n    // Empty cells\r\n    for(let i = 0; i < startDay; i++){\r\n\r\n      const empty = document.createElement('button');\r\n\r\n      empty.type = 'button';\r\n      empty.className = 'bd-cal-day empty';\r\n      empty.disabled = true;\r\n\r\n      grid.appendChild(empty);\r\n    }\r\n\r\n    // Dates\r\n    for(let d = 1; d <= daysInMonth; d++){\r\n\r\n      const cellDate = new Date(viewYear, viewMonth, d);\r\n\r\n      const cell = document.createElement('button');\r\n\r\n      cell.type = 'button';\r\n      cell.className = 'bd-cal-day';\r\n      cell.textContent = d;\r\n\r\n      if(sameDate(cellDate, today)){\r\n        cell.classList.add('today');\r\n      }\r\n\r\n      if(selectedDate && sameDate(cellDate, selectedDate)){\r\n        cell.classList.add('selected');\r\n      }\r\n\r\n      if(isPastDate(cellDate)){\r\n\r\n        cell.classList.add('disabled');\r\n        cell.disabled = true;\r\n\r\n      } else {\r\n\r\n        cell.addEventListener('click', function(){\r\n\r\n          selectDate(cellDate);\r\n\r\n        });\r\n\r\n      }\r\n\r\n      grid.appendChild(cell);\r\n    }\r\n  }\r\n\r\n  // =========================================================\r\n  // SELECT DATE\r\n  // =========================================================\r\n  function selectDate(dt){\r\n\r\n    selectedDate = dt;\r\n\r\n    const hiddenDate = document.getElementById('bd_date');\r\n\r\n    if(hiddenDate){\r\n      hiddenDate.value = fmtISO(dt);\r\n    }\r\n\r\n    renderCalendar();\r\n\r\n    const selectedDisplay =\r\n      document.getElementById('bdSelectedDisplay');\r\n\r\n    if(selectedDisplay){\r\n\r\n      selectedDisplay.innerHTML =\r\n        CAL_ICON +\r\n        '<span>Selected: <span class=\"bd-sel-date\">' +\r\n        fmtDisplay(dt) +\r\n        '</span></span>';\r\n    }\r\n\r\n    const echo =\r\n      document.getElementById('bdFormDateEcho');\r\n\r\n    const text =\r\n      document.getElementById('bdFormDateText');\r\n\r\n    if(text){\r\n      text.textContent = fmtDisplay(dt);\r\n    }\r\n\r\n    if(echo){\r\n      echo.classList.add('filled');\r\n    }\r\n\r\n    if(status){\r\n      status.innerHTML = '';\r\n    }\r\n  }\r\n\r\n  // =========================================================\r\n  // MONTH NAVIGATION\r\n  // =========================================================\r\n  document\r\n    .getElementById('bdCalPrev')\r\n    .addEventListener('click', function(){\r\n\r\n      viewMonth--;\r\n\r\n      if(viewMonth < 0){\r\n\r\n        viewMonth = 11;\r\n        viewYear--;\r\n\r\n      }\r\n\r\n      renderCalendar();\r\n    });\r\n\r\n  document\r\n    .getElementById('bdCalNext')\r\n    .addEventListener('click', function(){\r\n\r\n      viewMonth++;\r\n\r\n      if(viewMonth > 11){\r\n\r\n        viewMonth = 0;\r\n        viewYear++;\r\n\r\n      }\r\n\r\n      renderCalendar();\r\n    });\r\n\r\n  // =========================================================\r\n  // INITIAL CALENDAR\r\n  // =========================================================\r\n  renderCalendar();\r\n\r\n  // =========================================================\r\n  // FORM SUBMIT\r\n  // =========================================================\r\n  form.addEventListener('submit', function(e){\r\n\r\n    e.preventDefault();\r\n\r\n    // Validate form\r\n    if(!form.checkValidity()){\r\n\r\n      form.reportValidity();\r\n      return;\r\n    }\r\n\r\n    // Validate date\r\n    const hiddenDate = document.getElementById('bd_date');\r\n\r\n    if(!hiddenDate || !hiddenDate.value){\r\n\r\n      if(status){\r\n        status.innerHTML =\r\n          '<span class=\"bdf-error\">Please select a date.</span>';\r\n      }\r\n\r\n      return;\r\n    }\r\n\r\n    // Loading State\r\n    if(btnText){\r\n      btnText.style.display = 'none';\r\n    }\r\n\r\n    if(btnLoader){\r\n      btnLoader.style.display = 'inline-block';\r\n    }\r\n\r\n    if(submitBtn){\r\n      submitBtn.disabled = true;\r\n    }\r\n\r\n    // =========================================================\r\n    // FORM DATA\r\n    // =========================================================\r\n    const fd = new FormData(form);\r\n\r\n    const payload = {\r\n\r\n      name:\r\n        fd.get('name') ||\r\n        '',\r\n\r\n      phone:\r\n        fd.get('phone') ||\r\n        '',\r\n\r\n      email:\r\n        fd.get('email') ||\r\n        '',\r\n\r\n      course:\r\n        fd.get('course') ||\r\n        '',\r\n\r\n      mode:\r\n        fd.get('mode') ||\r\n        '',\r\n\r\n      date:\r\n        fd.get('date') ||\r\n        hiddenDate.value ||\r\n        '',\r\n\r\n      message:\r\n        fd.get('message') ||\r\n        '',\r\n\r\n      timestamp:\r\n        new Date().toLocaleString('en-IN',{\r\n          timeZone:'Asia/Kolkata'\r\n        }),\r\n\r\n      source:\r\n        window.location.href\r\n    };\r\n\r\n    console.log('📤 Sending Data:', payload);\r\n\r\n    // =========================================================\r\n    // FETCH\r\n    // =========================================================\r\n    fetch(SHEET_URL, {\r\n\r\n      method: 'POST',\r\n\r\n      mode: 'no-cors',\r\n\r\n      headers: {\r\n        'Content-Type':\r\n          'text/plain;charset=utf-8'\r\n      },\r\n\r\n      body: JSON.stringify(payload)\r\n\r\n    })\r\n\r\n    .then(function(){\r\n\r\n      console.log('✅ Submitted Successfully');\r\n\r\n      if(status){\r\n\r\n        status.innerHTML =\r\n          '<span class=\"bdf-success\">Demo booked successfully. We will contact you soon.</span>';\r\n      }\r\n\r\n      // Reset Form\r\n      form.reset();\r\n\r\n      selectedDate = null;\r\n\r\n      if(hiddenDate){\r\n        hiddenDate.value = '';\r\n      }\r\n\r\n      // Reset UI\r\n      const selectedDisplay =\r\n        document.getElementById('bdSelectedDisplay');\r\n\r\n      if(selectedDisplay){\r\n\r\n        selectedDisplay.innerHTML =\r\n          CAL_ICON +\r\n          '<span>Select a date to book your demo</span>';\r\n      }\r\n\r\n      const echo =\r\n        document.getElementById('bdFormDateEcho');\r\n\r\n      if(echo){\r\n        echo.classList.remove('filled');\r\n      }\r\n\r\n      const text =\r\n        document.getElementById('bdFormDateText');\r\n\r\n      if(text){\r\n        text.textContent =\r\n          '← Pick a date from the calendar';\r\n      }\r\n\r\n      renderCalendar();\r\n\r\n    })\r\n\r\n    .catch(function(error){\r\n\r\n      console.error('❌ Submission Failed:', error);\r\n\r\n      if(status){\r\n\r\n        status.innerHTML =\r\n          '<span class=\"bdf-error\">Could not submit form. Please try again.</span>';\r\n      }\r\n\r\n    })\r\n\r\n    .finally(function(){\r\n\r\n      // Reset Button\r\n      if(btnText){\r\n        btnText.style.display = 'inline';\r\n      }\r\n\r\n      if(btnLoader){\r\n        btnLoader.style.display = 'none';\r\n      }\r\n\r\n      if(submitBtn){\r\n        submitBtn.disabled = false;\r\n      }\r\n\r\n    });\r\n\r\n  });\r\n\r\n})();\r\n"}} />

    
    
    
    
    
    
 
